      http.use_ssl = uri.scheme == 'https'
      http.open_timeout = timeout
      http.read_timeout = timeout

      req = new_request(method, uri.request_uri, !body.nil?)
      req['Accept'] = 'application/json'
      headers.each { |k, v| req[k.to_s] = v }
      req.body = body if body
      http.request(req)
    end

    def self.build_query_string(params = nil, has_query: false, **keyword_params)
      params ||= keyword_params
      pairs = []
      params.each do |key, raw|
        query_value = raw.is_a?(QueryValue) ? raw : QueryValue.new(raw)
        value = query_value.value
        next if value.nil? || value.equal?(NOT_GIVEN)

        delimiter = { 'spaceDelimited' => ' ', 'pipeDelimited' => '|' }.fetch(query_value.style, ',')
        wire = deep_to_h(value)
        if wire.is_a?(::Hash)
          pairs.concat(object_query_pairs(key.to_s, wire, query_value, delimiter))
        elsif value.is_a?(::Array)
          values = query_value.explode ? value : [value.join(delimiter)]
          values.each { |item| pairs << [key.to_s, item.to_s] }
        else
          pairs << [key.to_s, value.to_s]
        end
      end
      return '' if pairs.empty?
      separator = has_query ? '&' : '?'
      separator + URI.encode_www_form(pairs)
    end

    # An object query value's pairs: `name[member]` (deepObject), one pair per
    # member (exploded form), or its members and values joined.
    def self.object_query_pairs(name, members, query_value, delimiter)
      joined = []
      pairs = members.each_with_object([]) do |(member, item), result|
        next if item.nil?

        if query_value.style == 'deepObject' && item.is_a?(::Hash)
          result.concat(object_query_pairs("#{name}[#{member}]", item, query_value, delimiter))
        elsif query_value.style == 'deepObject' then result << ["#{name}[#{member}]", simple_value(item, false)]
        elsif query_value.explode then result << [member.to_s, simple_value(item, false)]
        else joined.push(member.to_s, simple_value(item, false))
        end
      end
      joined.empty? ? pairs : pairs << [name, joined.join(delimiter)]
    end

    # A path segment in its declared style: `simple` ("a,b"), `label` (".a,b")
    # or `matrix` (";id=a,b"). An object is its "k,v" pairs, or "k=v" members
    # when exploded. Each item is encoded on its own, so the delimiters stay
    # literal and a comma inside an item is "%2C". URI::DEFAULT_PARSER.escape is
    # obsolete on Ruby 3.4, and its replacements need Ruby 3.2+; encoding the
    # bytes directly works on every supported Ruby.
    def self.encode_path_segment(value, name: '', style: 'simple', explode: false)
      escape = ->(text) { text.to_s.b.gsub(/[^A-Za-z0-9\-._~]/n) { |byte| format('%%%02X', byte.ord) } }
      wire = deep_to_h(value)
      object = wire.is_a?(::Hash)
      pairs = if object then wire.filter_map { |key, item| [key, member_text(item)] unless item.nil? }
              else (value.is_a?(::Array) ? value : [value]).map { |item| [name, item] }
              end
      texts = pairs.flat_map do |pair|
        encoded = pair.map(&escape)
        if explode && (object || style == 'matrix') then [encoded.join('=')]
        elsif object then encoded
        else encoded.drop(1)
        end
      end
      case style
      when 'label' then ".#{texts.join(explode ? '.' : ',')}"
      when 'matrix' then explode ? texts.map { |text| ";#{text}" }.join : ";#{name}=#{texts.join(',')}"
      else texts.join(',')
      end
    end

    def self.prepare_request(method, path, config:, query:, body:, content_type:, operation_id:)
      cfg = config || SdkConfig.config
      upper_method = method.to_s.upcase
      auth_headers, auth_query = resolve_auth(cfg, operation_id)
      merged_query = auth_query.empty? ? query : (query || {}).merge(auth_query)
      # Absolute URLs (used by url-style pagination follow links) bypass base_url.
      base = cfg.base_url || OPERATION_SERVERS[operation_id] || DEFAULT_BASE_URL
      url = path.match?(%r{\Ahttps?://}i) ? path : "#{base.to_s.chomp('/')}#{ascii_path(path)}"
      url += build_query_string(merged_query, has_query: path.include?('?')) if merged_query && !merged_query.empty?
      body_string, content_type = prepare_body(with_stream_selector(body, operation_id), content_type)
      [cfg, upper_method, url, auth_headers, body_string, content_type]
    end

    # `body` with its stream flag set for a stream call, or dropped for a plain one.
    def self.with_stream_selector(body, operation_id)
      name, value, streaming = STREAM_SELECTORS[operation_id]
      return body if name.nil? || body.equal?(NOT_GIVEN)
      # form_fields re-wraps the file fields of a form's value by name.
      return FormValue.new(with_stream_selector(body.value, operation_id), body.files) if body.is_a?(FormValue)

      # A hash keeps its UploadFile values; deep_to_h would read them as bytes.
      wire = body.is_a?(::Hash) ? body : deep_to_h(body)
      return body unless wire.is_a?(::Hash)

      kept = wire.reject { |key, item| key.to_s == name && (streaming || item == value) }
      streaming ? kept.merge(name => value) : kept
    end

    # A literal path segment is authored text (`/größe/`), and URI accepts ASCII only.
    # Literal path text a URI cannot carry (DigitalOcean's `/<upload_url>`,
    # non-ASCII names) is percent-encoded; an encoded parameter stays as it is.
    def self.ascii_path(path)
      path.gsub(%r{[^A-Za-z0-9\-._~!$&'()*+,;=:@/%?]+}) do |text|
        text.bytes.map { |byte| format('%%%02X', byte) }.join
      end
    end

    # Pairs a body that is one of `files`' models with its binary fields.
    def self.form_value(body, files)
      files.key?(body.class) ? FormValue.new(body, files[body.class]) : body
    end

    # Bytes a body sends as a file part under multipart, and as they are in JSON.
    def self.upload(value, filename)
      case value
      when ::String then UploadFile.new(data: value, filename: filename)
      when ::Array then value.map { |item| upload(item, filename) }
      else value
      end
    end

    # A model's wire fields under a form media type, its binary ones as files.
    def self.form_fields(form, content_type)
      return form.value unless content_type.start_with?('multipart/form-data', 'application/x-www-form-urlencoded')

      deep_to_h(form.value).to_h do |name, value|
        next [name, value] unless form.files.include?(name)

        file = ->(data) { data.is_a?(::String) ? UploadFile.new(data: data, filename: name) : data }
        [name, value.is_a?(::Array) ? value.map(&file) : file.call(value)]
      end
    end

    def self.prepare_body(body, content_type)
      body = form_fields(body, content_type) if body.is_a?(FormValue)
      return [encode_body(body, content_type), content_type] unless content_type.start_with?('multipart/form-data') && body.is_a?(::Hash)

      boundary = "----InterfacerFormBoundary#{rand(36**24).to_s(36)}"
      [encode_multipart(body, boundary), "multipart/form-data; boundary=#{boundary}"]
    end

    # The operation's headers, with its cookies joined into one Cookie header.
    def self.serialize_headers(values, cookies: [])
      headers = values.each_with_object({}) do |(key, value), result|
        next if value.nil? || value.equal?(NOT_GIVEN)
        result[key.to_s] = value.to_s
      end
      pairs = cookies.flatten
      headers['Cookie'] = pairs.join('; ') unless pairs.empty?
      headers
    end

    # A header parameter in OpenAPI's simple style: array items join with commas
    # and object members become key,value pairs, or key=value pairs when exploded.
    def self.header_value(value, explode: false)
      return nil if value.nil? || value.equal?(NOT_GIVEN)

      simple_value(deep_to_h(value), explode)
    end

    # One cookie parameter in OpenAPI's form style, percent-encoded: an exploded
    # array repeats the name and an exploded object sends one pair per member.
    def self.cookie(name, value, explode: true)
      return [] if value.nil? || value.equal?(NOT_GIVEN)

      wire = deep_to_h(value)
      members = if explode && wire.is_a?(::Array) then wire.map { |item| [name, item] }
                elsif explode && wire.is_a?(::Hash) then wire.to_a
                else [[name, wire]]
                end
      members.map { |key, item| "#{key}=#{encode_path_segment(simple_value(item, false))}" }
    end

    # The JSON text of a parameter whose content is application/json.
    def self.json_parameter(value)
      return value if value.nil? || value.equal?(NOT_GIVEN)

      JSON.generate(deep_to_h(value))
    end

    def self.simple_value(value, explode)
      case value
      when ::Array then value.map { |item| member_text(item) }.join(',')
      when ::Hash then value.map { |key, item| "#{key}#{explode ? '=' : ','}#{member_text(item)}" }.join(',')
      else value.to_s
      end
    end

    # A nested list or object has no simple-style form but its JSON.
    def self.member_text(value)
      value.is_a?(::Array) || value.is_a?(::Hash) ? JSON.generate(value) : value.to_s
    end

    # Merges headers, joining a Cookie onto one already present: an apiKey
    # cookie and the operation's cookies share the single Cookie header.
    def self.merge_headers(headers, extra)
      (extra || {}).each_with_object(headers.dup) do |(key, value), merged|
        cookie = key.to_s.casecmp?('Cookie') && merged.keys.find { |name| name.to_s.casecmp?('Cookie') }
        if cookie
          merged[cookie] = "#{merged[cookie]}; #{value}"
        else
          merged[key] = value
        end
      end
    end

    def self.build_headers(config, auth_headers, content_type, has_body)
      headers = {}
      auth = config.auth
      auth&.headers&.each { |k, v| headers[k.to_s] = v }
      auth_headers.each { |k, v| headers[k.to_s] = v }
      headers['Content-Type'] = content_type if has_body
      headers
    end

    # Resolves all configured auth into [headers, query_params]. OAuth2 fetch
    # happens here, before the retry loop starts.
    def self.resolve_auth(config, operation_id)
      headers = {}
      query = {}
      auth = config.auth
      return [headers, query] unless auth


      headers["Authorization"] = "Bearer #{auth.bearer_token}" if auth.bearer_token

      if auth.oauth2
        token = oauth2_access_token(auth.oauth2, "oauth2", "https://api.vercel.com/oauth/access_token", "https://api.vercel.com/oauth/access_token", operation_id)
        headers["Authorization"] = "Bearer #{token}"
      end

      [headers, query]
    end


    @oauth2_cache = {}
    @oauth2_cache_mutex = Mutex.new
    # Token requests in flight, per owner and key, so concurrent requests that
    # find the same token missing or expired share one request to the endpoint.
    OAuth2Flight = ::Struct.new(:done, :value, :error)
    @oauth2_flights = {}
    @oauth2_flights_mutex = Mutex.new
    @oauth2_flights_done = ConditionVariable.new
    OAUTH2_EXPIRY_SKEW_S = 30.0
    OPERATION_SCOPES = {

    }.freeze

    def self.oauth2_token_request(scheme, token_url, refresh_url, operation_id)
      scopes = OPERATION_SCOPES.fetch(operation_id, {}).fetch(scheme, [])
      OAuth2TokenRequest.new(scheme: scheme, token_url: token_url, refresh_url: refresh_url, scopes: scopes)
    end

    # The access token for an OAuth 2 scheme: from its configured provider, or
    # fetched from the token endpoint and cached.
    def self.oauth2_access_token(credentials, scheme, token_url, refresh_url, operation_id)
      return resolve_oauth2_token(credentials, token_url) unless credentials.provider

      request = oauth2_token_request(scheme, token_url, refresh_url, operation_id)
      provider_access_token(credentials.provider, operation_id, request)
    end

    # Runs the block once for concurrent callers asking for the same token;
    # every caller receives that one result or error.
    def self.single_flight(owner, key)
      id = [owner.object_id, key]
      flight = @oauth2_flights_mutex.synchronize do
        if (pending = @oauth2_flights[id])
          @oauth2_flights_done.wait(@oauth2_flights_mutex) until pending.done
          raise pending.error if pending.error

          return pending.value
        end
        @oauth2_flights[id] = OAuth2Flight.new(false)
      end
      begin
        flight.value = yield
      rescue ::StandardError => e
        flight.error = e
        raise
      ensure
        @oauth2_flights_mutex.synchronize do
          flight.done = true
          @oauth2_flights.delete(id)
          @oauth2_flights_done.broadcast
        end
      end
    end

    def self.usable_oauth2_token?(token)
      return false if token.access_token.to_s.empty?

      token.expires_at.nil? || token.expires_at > Time.now + OAUTH2_EXPIRY_SKEW_S
    end

    # Asks the provider for a token, and for a refresh when that token is not
    # usable. Raised inside +rescue+, the provider error keeps the failure as
    # its +cause+.
    def self.provider_access_token(provider, operation_id, request)
      token = begin
        provider.get_access_token(request)
      rescue ::StandardError
        raise oauth2_provider_error(operation_id, request, 'could not obtain an access token')
      end
      return token.access_token if usable_oauth2_token?(token)

      token = begin
        single_flight(provider, "#{request.scheme}|#{request.scopes.sort.join(' ')}") do
          provider.refresh_access_token(request)
        end
      rescue ::StandardError
        raise oauth2_provider_error(operation_id, request, 'could not refresh the expired access token')
      end
      return token.access_token if usable_oauth2_token?(token)

      raise oauth2_provider_error(operation_id, request, 'obtained no usable access token')
    end

    def self.oauth2_provider_error(operation_id, request, summary)
      suffix = operation_id.empty? ? '' : " for operation #{operation_id}"
      SdkAuthProviderError.new(
        operation_id: operation_id, scheme: request.scheme, scopes: request.scopes,
        message: "auth oauth2 #{summary}#{suffix}",
      )
    end

    def self.resolve_oauth2_token(auth, default_token_url)
      return auth.access_token if auth.access_token
      token_url = auth.token_url || default_token_url
      raise SdkNetworkError, ::StandardError.new("oauth2: token_url is required for client credentials flow") if token_url.empty?

      sorted_scopes = (auth.scopes || []).sort
      cache_key = "#{auth.client_id}|#{token_url}|#{sorted_scopes.join(',')}"
      cached = @oauth2_cache_mutex.synchronize { @oauth2_cache[cache_key] }
      if cached && cached[:expires_at] > Time.now + OAUTH2_EXPIRY_SKEW_S
        return cached[:access_token]
      end

      single_flight(@oauth2_cache, cache_key) { exchange_client_credentials(auth, token_url, cache_key) }
    end

    # Runs the client-credentials grant and caches the issued token.
    def self.exchange_client_credentials(auth, token_url, cache_key)
      form = {
        'grant_type' => 'client_credentials',
        'client_id' => auth.client_id || '',
        'client_secret' => auth.client_secret || '',
      }
      form['scope'] = auth.scopes.join(' ') if auth.scopes && !auth.scopes.empty?

      payload = post_token_form(token_url, form)
      access_token = payload['access_token']
      raise SdkNetworkError, ::StandardError.new("oauth2: token response missing access_token") unless access_token.is_a?(::String)
      expires_in = payload['expires_in'] || 3600
      @oauth2_cache_mutex.synchronize do
        @oauth2_cache[cache_key] = { access_token: access_token, expires_at: Time.now + expires_in.to_f }
      end
      access_token
    end

    # POSTs a token-endpoint form and returns the decoded JSON response.
    def self.post_token_form(token_url, form)
      uri = URI.parse(token_url)
      http = Net::HTTP.new(uri.host, uri.port)
      http.use_ssl = uri.scheme == 'https'
      req = Net::HTTP::Post.new(uri.request_uri)
      req['Content-Type'] = 'application/x-www-form-urlencoded'
      req['Accept'] = 'application/json'
      req.body = URI.encode_www_form(form)
      response = http.request(req)
      unless response.is_a?(Net::HTTPSuccess)
        raise SdkHttpError.for_status(
          status_code: response.code.to_i, status_text: response.message.to_s,
          body: response.body.to_s, headers: {}, request_id: nil,
        )
      end

      JSON.parse(response.body)
    end

    # The media type a multi-content body is sent as: the one named, else the
    # one its value implies. A binary String is bytes; any other is text.
    def self.body_content_type(named, body, default, bytes: nil, text: nil, array: nil)
      return named unless named.equal?(NOT_GIVEN)

      if body.is_a?(::String)
        (body.encoding == Encoding::BINARY ? bytes || text : text || bytes) || default
      elsif body.is_a?(::Array)
        array || default
      else
        default
      end
    end

    def self.encode_body(body, content_type)
      return nil if body.equal?(NOT_GIVEN)

      media_type = content_type.split(';').first.to_s.strip.downcase
      return encode_json_records(body, media_type) if JSON_SEQUENCE_MEDIA_TYPES.include?(media_type)
      return JSON.generate(deep_to_h(body)) if content_type.include?('json')
      return encode_form(body) if media_type == 'application/x-www-form-urlencoded' && body.is_a?(::Hash)
      return '' if body.nil?
      body.to_s
    end

    # A repeated field repeats its name; a structured value is sent as JSON.
    def self.encode_form(fields)
      pairs = fields.reject { |_, value| value.equal?(NOT_GIVEN) }.flat_map do |key, value|
        (value.is_a?(::Array) ? value : [value]).map { |item| [key.to_s, item.nil? ? 'null' : member_text(deep_to_h(item))] }
      end
      URI.encode_www_form(pairs)
    end

    # One JSON record per line; a JSON text sequence also starts each with RS.
    def self.encode_json_records(body, media_type)
      separator = media_type == 'application/json-seq' ? "\x1E" : ''
      (body.is_a?(::Array) ? body : [body]).map { |record| "#{separator}#{JSON.generate(deep_to_h(record))}\n" }.join
    end

    # One NDJSON line's record, without the RS a JSON text sequence record starts with.
    def self.json_record_text(line)
      line.strip.delete_prefix("\x1E")
    end

    # Builds schema-aware multipart data with repeated uploads and metadata.
    def self.encode_multipart(fields, boundary)
      out = ::String.new(encoding: Encoding::ASCII_8BIT)
      multipart_entries(fields).each do |key, value, content_type|
        append_multipart_part(out, boundary, key, value, content_type)
      end
      out << "--#{boundary}--\r\n".b
      out
    end

    def self.multipart_entries(fields)
      fields.flat_map do |key, raw|
        case raw
        when MultipartPart
          raw.value.equal?(NOT_GIVEN) ? [] : [[key, raw.value, raw.content_type]]
        when ::Array
          raw.flat_map { |item| multipart_entries(key => item) }
        else
          raw.equal?(NOT_GIVEN) ? [] : [[key, raw, nil]]
        end
      end
    end

    def self.append_multipart_part(out, boundary, key, value, content_type)
      disposition = %(Content-Disposition: form-data; name="#{escape_multipart_token(key)}")
      if value.is_a?(UploadFile)
        disposition << %(; filename="#{escape_multipart_token(value.filename)}")
        content_type = value.content_type
        payload = value.data
      elsif multipart_json_value?(value, content_type)
        content_type ||= 'application/json'
        payload = JSON.generate(deep_to_h(value)).b
      else
        payload = value.nil? ? 'null'.b : value.to_s.b
      end
      out << "--#{boundary}\r\n#{disposition}\r\n".b
      out << "Content-Type: #{content_type}\r\n".b if content_type
      out << "\r\n".b << payload << "\r\n".b
    end

    def self.escape_multipart_token(value)
      value.to_s.gsub(/["\\]/) { |char| "\\#{char}" }
    end

    def self.multipart_json_value?(value, content_type)
      return true if content_type || value.is_a?(::Hash)
      return false if value.nil?

      scalar_types = [::String, ::Integer, ::Float, ::TrueClass, ::FalseClass]
      scalar_types.none? { |type| value.is_a?(type) }
    end

    def self.flatten_headers(response)
      out = {}
      response.each_header { |name, value| out[name.downcase] = value }
      out
    end

    def self.find_request_id(headers)
      REQUEST_ID_HEADERS.each { |name| return headers[name] if headers[name] }
      nil
    end

    def self.retry_status?(method, status, retry_on)
      return false unless retry_on.include?(status)
      return true if IDEMPOTENT_METHODS.include?(method)
      ALWAYS_RETRYABLE_STATUSES.include?(status)
    end

    # An attempt that produced no response may already have been applied, so a
    # non-idempotent method is repeated only with a key sent to an operation
    # that declares the server deduplicates on it.
    def self.may_repeat_request?(method, operation_id, idempotency_key)
      return true if IDEMPOTENT_METHODS.include?(method)
      !idempotency_key.nil? && IDEMPOTENCY_KEY_OPERATIONS.include?(operation_id)
    end

    def self.sleep_backoff(retry_cfg, attempt, retry_after)
      max_sec = retry_cfg.max_backoff
      wait =
        if retry_after.to_s.match?(/\A\d+\z/)
          [retry_after.to_i, max_sec].min
        else
          exp = retry_cfg.backoff * (2**(attempt - 1))
          jitter = rand * retry_cfg.backoff
          [exp + jitter, max_sec].min
        end
      sleep(wait) if wait.positive?
    end

    # The body of a 2xx response. One whose envelope reports an error raises
    # SdkApiError; one that does not decode raises SdkResponseDecodeError.
    def self.decode_response(raw, decoder, return_type, operation_id)
      return decode_body(raw.body, decoder, return_type) unless decoder == :json

      data = JSON.parse(raw.body)
      raise_error_envelope(raw, data, operation_id)
      decode_typed(data, return_type)
    rescue JSON::ParserError, SdkValidationError => error
      raise SdkResponseDecodeError.new(
        error.message, status_code: raw.status_code, headers: raw.headers, body: raw.body,
                       request_id: raw.request_id, field: error.respond_to?(:field) ? error.field : nil
      )
    end

    def self.raise_error_envelope(raw, data, operation_id)
      field, equals, code_field = ERROR_ENVELOPES[operation_id]
      return unless field && data.is_a?(::Hash) && data.key?(field) && data[field] == equals

      code = code_field && data[code_field]
      raise SdkApiError.new(
        status_code: raw.status_code, status_text: '', body: data, headers: raw.headers,
        request_id: raw.request_id, code: code&.to_s
      )
    end

    # A stream event decoded into its type; one that does not decode raises
    # SdkResponseDecodeError with its data.
    def self.decode_event(data, return_type)
      decode_typed(data, return_type)
    rescue SdkValidationError => error
      raise SdkResponseDecodeError.new(error.message, status_code: 200, headers: {}, body: data, field: error.field)
    end

    def self.decode_body(text, decoder, return_type)
      return nil if decoder == :empty
      return text.b if decoder == :bytes
      return text.dup.force_encoding(Encoding::UTF_8) if decoder == :text
      data = JSON.parse(text)
      decode_typed(data, return_type)
    end

    def self.decode_typed(data, return_type)
      return data if return_type.nil?
      if return_type.is_a?(::Array)
        return data unless data.is_a?(::Array)

        item_type = return_type.first
        return data.map { |item| decode_typed(item, item_type) }
      end
      if return_type.is_a?(::Hash)
        return data unless data.is_a?(::Hash)

        value_type = return_type.values.first
        return data.transform_values { |value| decode_typed(value, value_type) }
      end
      return_type.respond_to?(:from_hash) ? return_type.from_hash(data) : data
    end

    # Opens an SSE connection and yields parsed events. Bypasses the retry
    # loop and idempotency layer — streaming connections are long-lived;
    # reconnect is the caller's responsibility. Returns an Enumerator when
    # called without a block, so callers can use .lazy / .first / .each.
    #
    # @yield [SdkStreamEvent]
    # @return [Enumerator] when no block is given
    def self.stream(method, path, config: nil, query: nil, body: NOT_GIVEN, content_type: 'application/json', operation_id: '', stream_format: :sse, stream_media_type: 'text/event-stream', chunk_domain: :bytes, extra_headers: nil, request_options: nil, errors: {}, &block)
      return enum_for(:stream, method, path, config: config, query: query, body: body, content_type: content_type, operation_id: operation_id, stream_format: stream_format, stream_media_type: stream_media_type, chunk_domain: chunk_domain, extra_headers: extra_headers, request_options: request_options, errors: errors) unless block_given?

      cfg, upper_method, url, auth_headers, body_string, content_type = prepare_request(
        method,
        path,
        config: config,
        query: query,
        body: body,
        content_type: content_type,
        operation_id: operation_id,
      )

      headers = build_headers(cfg, auth_headers, content_type, !body.equal?(NOT_GIVEN))
      headers = merge_headers(merge_headers(headers, extra_headers), request_options&.headers)
      headers['Accept'] = stream_media_type

      http, request = build_http_request(
        upper_method,
        url,
        config: cfg,
        headers: headers,
        body_string: body_string,
      )
      http.request(request) do |response|
        consume_stream_response(response, stream_format, chunk_domain, errors, &block)
      end
    end

    def self.build_http_request(method, url, config:, headers:, body_string:)
      uri = parse_request_uri(url)
      http = Net::HTTP.new(uri.host, uri.port)
      http.use_ssl = uri.scheme == 'https'
      http.open_timeout = config.timeout
      http.read_timeout = config.timeout

      req = new_request(method, uri.request_uri, !body_string.nil?)
      headers.each { |k, v| req[k.to_s] = v }
      req.body = body_string if body_string
      [http, req]
    end

    def self.consume_stream_response(response, stream_format, chunk_domain, errors, &block)
      raise_stream_error(response, errors) unless response.code.to_i.between?(200, 299)
      refuse_json_answer(response) if stream_format == :sse

      if stream_format == :chunked
        response.read_body do |chunk|
          data = chunk_domain == :text ? chunk.dup.force_encoding(Encoding::UTF_8) : chunk.b
          block.call(SdkStreamEvent.new(event: 'chunk', data: data))
        end
        return
      end

      if stream_format == :ndjson
        buffer = +''
        response.read_body do |chunk|
          buffer << chunk
          while (newline = buffer.index("\n"))
            line = json_record_text(buffer.slice!(0, newline + 1))
            block.call(SdkStreamEvent.new(data: line)) unless line.empty?
          end
        end
        line = json_record_text(buffer)
        block.call(SdkStreamEvent.new(data: line)) unless line.empty?
        return
      end

      parser = SseParser.new
      response.read_body do |chunk|
        parser.feed(chunk).each { |event| block.call(event) }
      end
      event = parser.finish
      block.call(event) if event
    end

    # An event stream answered with plain JSON, as by a server that ignored the
    # stream flag, fails: its parser would yield no events at all.
    def self.refuse_json_answer(response)
      content_type = response['content-type'].to_s
      media_type = content_type.split(';').first.to_s.strip.downcase
      return unless media_type == 'application/json' || media_type.end_with?('+json')

      response_body = ::String.new
      response.read_body { |chunk| response_body << chunk }
      response_headers = flatten_headers(response)
      raise SdkResponseDecodeError.new(
        "Expected an event stream, received #{content_type}", status_code: response.code.to_i,
                                                               headers: response_headers, body: response_body,
                                                               request_id: find_request_id(response_headers)
      )
    end

    def self.raise_stream_error(response, errors)
      response_body = ::String.new
      response.read_body { |chunk| response_body << chunk }
      response_headers = flatten_headers(response)
      raise SdkHttpError.for_status(
        status_code: response.code.to_i,
        status_text: response.message.to_s,
        body: response_body,
        headers: response_headers,
        request_id: find_request_id(response_headers),
        errors: errors,
      )
    end

    # Polls a long-running operation until terminal. is_terminal returns
    # [done, failed, reason]. Raises SdkTimeoutError on deadline.
    def self.wait_for(poll, is_terminal, config: nil)
      cfg = config || WaitForConfig.new
      deadline = Time.now + cfg.timeout
      interval = cfg.interval
      loop do
        result = poll.call
        done, failed, reason = is_terminal.call(result)
        if done
          raise SdkNetworkError, RuntimeError.new("operation failed: #{reason || 'unknown'}") if failed
          return result
        end
        raise SdkTimeoutError, cfg.timeout if Time.now >= deadline
        jitter = rand * cfg.interval
        wait = [interval + jitter, cfg.max_interval].min
        sleep(wait)
        interval = [interval * 2, cfg.max_interval].min
      end
    end
  end


  # The built-in provider for the refresh-token grant: it refreshes the access
  # token before it expires and adopts each refresh token the server rotates
  # in, passing it to on_refresh_token_rotated so it can be persisted.
  class OAuth2RefreshTokenProvider
    # refresh_url overrides the request's refresh_url.
    def initialize(refresh_token:, client_id: nil, client_secret: nil, refresh_url: nil, on_refresh_token_rotated: nil)
      @refresh_token = refresh_token
      @client_id = client_id
      @client_secret = client_secret
      @refresh_url = refresh_url
      @on_refresh_token_rotated = on_refresh_token_rotated
      @token = OAuth2Token.new(access_token: '')
    end

    def get_access_token(_request)
      @token
    end

    def refresh_access_token(request)
      form = { 'grant_type' => 'refresh_token', 'refresh_token' => @refresh_token }
      form['client_id'] = @client_id if @client_id
      form['client_secret'] = @client_secret if @client_secret
      payload = SdkClient.post_token_form(@refresh_url || request.refresh_url, form)
      @token = OAuth2Token.new(
        access_token: payload['access_token'].to_s,
        expires_at: Time.now + (payload['expires_in'] || 3600).to_f,
      )
      rotated = payload['refresh_token']
      if rotated && rotated != @refresh_token
        @refresh_token = rotated
        @on_refresh_token_rotated&.call(rotated)
      end
      @token
    end
  end


  # A PKCE code verifier and the S256 challenge derived from it (RFC 7636).
  class OAuth2PkcePair
    attr_reader :verifier, :challenge, :challenge_method

    def initialize(verifier:, challenge:, challenge_method: 'S256')
      @verifier = verifier
      @challenge = challenge
      @challenge_method = challenge_method
    end
  end

  # The tokens an authorization code is redeemed for; persist refresh_token to
  # renew access without another login.
  class OAuth2AuthorizationCodeTokens
    attr_reader :access_token, :expires_at, :refresh_token

    def initialize(access_token:, expires_at:, refresh_token: nil)
      @access_token = access_token
      @expires_at = expires_at
      @refresh_token = refresh_token
    end
  end

  # The authorization-code flow with PKCE. The application owns the browser,
  # the redirect, and checking state when the user comes back.
  module OAuth2Pkce
    module_function

    # Creates a PKCE verifier and its S256 challenge. Keep the verifier with
    # the login attempt until its authorization code is exchanged.
    def create_pkce_pair
      verifier = SecureRandom.urlsafe_base64(32)
      challenge = [Digest::SHA256.digest(verifier)].pack('m0').tr('+/', '-_').delete('=')
      OAuth2PkcePair.new(verifier: verifier, challenge: challenge)
    end

    # The authorization-code URL to send the user to. authorization_url
    # overrides the spec's.
    def build_authorization_url(client_id:, redirect_uri:, code_challenge:, scopes: nil, state: nil, authorization_url: nil)
      params = {
        'response_type' => 'code',
        'client_id' => client_id,
        'redirect_uri' => redirect_uri,
        'code_challenge' => code_challenge,
        'code_challenge_method' => 'S256',
      }
      params['scope'] = scopes.join(' ') if scopes && !scopes.empty?
      params['state'] = state unless state.nil?
      base = authorization_url || "https://api.vercel.com/oauth/authorize"
      "#{base}#{base.include?('?') ? '&' : '?'}#{URI.encode_www_form(params)}"
    end

    # Redeems an authorization code and its PKCE verifier at the token
    # endpoint. token_url overrides the spec's.
    def exchange_authorization_code(code:, code_verifier:, redirect_uri:, client_id:, client_secret: nil, token_url: nil)
      form = {
        'grant_type' => 'authorization_code',
        'code' => code,
        'redirect_uri' => redirect_uri,
        'client_id' => client_id,
        'code_verifier' => code_verifier,
      }
      form['client_secret'] = client_secret if client_secret
      payload = SdkClient.post_token_form(token_url || "https://api.vercel.com/oauth/access_token", form)
      access_token = payload['access_token']
      raise SdkNetworkError, ::StandardError.new('oauth2: token response missing access_token') unless access_token.is_a?(::String)

      OAuth2AuthorizationCodeTokens.new(
        access_token: access_token,
        expires_at: Time.now + (payload['expires_in'] || 3600).to_f,
        refresh_token: payload['refresh_token'],
      )
    end
  end


  # One Server-Sent Event yielded by SdkClient.stream. @data is the raw event
  # payload; consumers can JSON-decode it themselves when applicable.
  class SdkStreamEvent
    attr_accessor :event, :data, :id, :retry

    def initialize(event: 'message', data: '', id: nil, retry: nil)
      @event = event
      @data = data
      @id = id
      @retry = binding.local_variable_get(:retry)
    end
  end

  # Configuration for SdkClient.wait_for.
  class WaitForConfig
    attr_accessor :interval, :max_interval, :timeout

    def initialize(interval: 1.0, max_interval: 30.0, timeout: 600.0)
      @interval = interval
      @max_interval = max_interval
      @timeout = timeout
    end
  end
end
